from robot.api import logger

from ta_egate_cmd_parser.egate_output_parser_base import EgateDispCommandsOutputParser
from ta_egate_cmd_parser.egate_command_base import EgateCommandBase
from ta_egate_cmd_parser.utils.converters import create_dict_with_key


class LaaCellCountersFailure(Exception):
    """
    Exception class for laa_cell_counters
    """
    pass


class LaaCellCounters(EgateCommandBase):
    """
    Parser for laa_cell_counters command output.
    """

    def __init__(self, **params):
        """

        :param params:
        """
        super(LaaCellCounters, self).__init__()
        self.command = 'laa_cell_counters'
        self.params = params
        self.fail_regexp = 'Error'
        self.to_execute = self.command
        self._build_command()
        logger.debug('{}: {} command to execute:\n{}'.format(self.__class__.__name__, self.command, self.to_execute))

    def _build_command(self):
        """
        Build laa_cell_counters command.
        :return: None
        """
        for param, value in list(self.params.items()):
            if param == 'display' or param == 'clear':
                self.to_execute += ' {}'.format(param)
            else:
                self.to_execute += ' {}={}'.format(param, value)

    def execute(self, egate_id=0):
        """
        Execute egate cmd.
        :return: parsed output
        """
        if 'clear' not in list(self.params.keys()):
            raise LaaCellCountersFailure("Use execute_and_parse() method to parse output of {} cmd".format(self.command))
        else:
            self.executed_phrase = '.*?EGATE>'
            status, output = super(LaaCellCounters, self).execute(egate_id=egate_id, command=self.to_execute)
            if status:
                return status, output
            else:
                raise LaaCellCountersFailure(output)

    def execute_and_parse(self, egate_id=0):
        """
        Execute egate cmd and parse its output.
        :return:
        """
        if 'clear' not in list(self.params.keys()):
            self.executed_phrase = r'.*?eNB-\d+\scell-\d+.*?EGATE>'
            status, output = super(LaaCellCounters, self).execute(egate_id=egate_id, command=self.to_execute)
            if status:
                cmd_parser = EgateDispCommandsOutputParser(output)
                output = cmd_parser.get_list_of_output_parsed_lines()
                return create_dict_with_key(key='LAA COUNTER',
                                            list_of_output_parsed_lines=output)
        else:
            raise LaaCellCountersFailure("Use execute() method to execute {} cmd with clear param".format(self.command))
